function validate([matrix, target]) {
  if (matrix.length < 1 || matrix.length > 300) return 'matrix needs 1 to 300 rows.';
  const n = matrix[0].length;
  if (n < 1 || n > 300) return 'Each row needs 1 to 300 values.';
  for (let i = 0; i < matrix.length; i++) {
    if (matrix[i].length !== n) return 'Every row must have the same length.';
    for (let j = 0; j < n; j++) {
      const value = matrix[i][j];
      if (value < -1e9 || value > 1e9) return 'Each value is between -10^9 and 10^9.';
      if (j > 0 && matrix[i][j - 1] > value) return 'Each row must be sorted in ascending order.';
      if (i > 0 && matrix[i - 1][j] > value) return 'Each column must be sorted in ascending order.';
    }
  }
  if (target < -1e9 || target > 1e9) return 'target is between -10^9 and 10^9.';
  return null;
}

