function generate(rand, size) {
  const large = size === 'large';
  const m = large ? 100 : 1 + Math.floor(rand() * 4);
  const n = large ? 100 : 1 + Math.floor(rand() * 4);
  const step = large ? 10000000 : 3;
  const start = large ? -1000000000 + Math.floor(rand() * 1000) : -6 + Math.floor(rand() * 6);
  const matrix = [];
  for (let i = 0; i < m; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      const above = i > 0 ? matrix[i - 1][j] : start;
      const left = j > 0 ? row[j - 1] : start;
      row.push(Math.max(above, left) + Math.floor(rand() * (step + 1)));
    }
    matrix.push(row);
  }
  const low = matrix[0][0], high = matrix[m - 1][n - 1];
  // Half the time search for a value that is present, otherwise any value near the grid's range.
  const target = rand() < 0.5
    ? matrix[Math.floor(rand() * m)][Math.floor(rand() * n)]
    : Math.max(-1000000000, Math.min(1000000000, low - 2 + Math.floor(rand() * (high - low + 5))));
  return [matrix, target];
}
